package main

import (
	"os"
	"strings"
	"testing"
)

const registryPath = "../../../docs/99-codes.md"

// TestGeneratedRegistryIsCurrent fails when docs/99-codes.md no longer matches
// what the registry would produce. Without this, the generated file silently
// rots the first time somebody adds a code and forgets to re-run go generate —
// which is the exact failure mode that made a hand-maintained registry document
// unacceptable in the first place.
func TestGeneratedRegistryIsCurrent(t *testing.T) {
	committed, err := os.ReadFile(registryPath)
	if err != nil {
		t.Fatalf("read %s: %v (run: go generate ./internal/codes/)", registryPath, err)
	}
	generated := Render()
	if string(committed) == string(generated) {
		return
	}

	t.Errorf("%s is stale; run: go generate ./internal/codes/", registryPath)

	cl := strings.Split(string(committed), "\n")
	gl := strings.Split(string(generated), "\n")
	for i := 0; i < len(cl) || i < len(gl); i++ {
		c, g := lineAt(cl, i), lineAt(gl, i)
		if c != g {
			t.Errorf("first difference at line %d:\n  committed: %q\n  generated: %q", i+1, c, g)
			return
		}
	}
}

// TestRenderIsDeterministic guards the ordering the document depends on: map
// iteration leaking into the output would produce a file that is stale on every
// other run and a test that fails at random.
func TestRenderIsDeterministic(t *testing.T) {
	first := string(Render())
	for i := 0; i < 5; i++ {
		if got := string(Render()); got != first {
			t.Fatalf("render %d differs from the first run", i+1)
		}
	}
}

func TestRenderHasDoNotEditBanner(t *testing.T) {
	if !strings.HasPrefix(string(Render()), "<!-- Code generated by") {
		t.Error("generated document does not start with the do-not-edit banner")
	}
}

func lineAt(lines []string, i int) string {
	if i < len(lines) {
		return lines[i]
	}
	return "<absent>"
}
